{#- Code generated by xgen. DO NOT EDIT.
    Source: xgen/specs/organisms/logo-cloud.json
    A heading and the names of customers or partners as Lucide glyphs with a name. Axes: layout (grid, row), columns (2, 3, 4), item (name, icon only, tile), density, tone.
    Props (p): id, title, logos, layout, cols, item, tone, density, landmarkLabel. -#}
{%- set v_id = (p.id ?? null) -%}
{%- set v_title = (p.title ?? null) -%}
{%- set v_logos = (p.logos ?? null) -%}
{%- set v_layout = (p.layout ?? 'grid') -%}
{%- set v_cols = (p.cols ?? '4') -%}
{%- set v_item = (p.item ?? 'name') -%}
{%- set v_tone = (p.tone ?? 'default') -%}
{%- set v_density = (p.density ?? 'default') -%}
{%- set v_landmarkLabel = (p.landmarkLabel ?? null) -%}
{%- if ui_t(ui_eq(v_layout, 'row')) %}
  {{ include('blocks/logo-ribbon.html.twig', {'p': {'id': v_id, 'title': v_title, 'logos': v_logos, 'tone': v_tone, 'density': v_density, 'landmarkLabel': v_landmarkLabel}}, with_context = false) }}
{%- else %}
  {%- set c_4 -%}
    {%- set c_3 -%}
      {%- for v_logo in ui_l(v_logos) %}
        {%- set c_2 -%}
          {{ include('ui/lucide-icon/lucide-icon.html.twig', {'p': {'Name': ui_s(ui_get(v_logo, ['icon'])), 'Size': 24}}, with_context = false) }}
          {%- set c_1 -%}
            {{ ui_text(ui_get(v_logo, ['name'])) }}
          {%- endset -%}
          {{ include('ui/text/text.html.twig', {'p': {'Size': 'sm', 'Weight': 'semibold', 'Class': ui_s((ui_t(ui_eq(v_item, 'icon')) ? 'sr-only' : ''))}, 'children': c_1}, with_context = false) }}
        {%- endset -%}
        {{ include('ui/group/group.html.twig', {'p': {'Gap': '2', 'Align': 'center', 'Justify': 'center', 'Class': ui_s(ui_cnv(['text-muted-foreground', (ui_t(ui_eq(v_item, 'tile')) ? 'flex-col rounded p-4 inset-ring inset-ring-border' : '')])), 'Attrs': ui_attrs(['data-testid', 'item'])}, 'children': c_2}, with_context = false) }}
      {%- endfor %}
    {%- endset -%}
    {{ include('ui/grid/grid.html.twig', {'p': {'Cols': ui_s((ui_t(ui_eq(v_cols, '2')) ? '2' : (ui_t(ui_eq(v_cols, '3')) ? '2-3' : (ui_t(ui_eq(v_cols, '4')) ? '2-4' : '3-6')))), 'Class': 'gap-4', 'Attrs': ui_attrs(['data-testid', 'items'])}, 'children': c_3}, with_context = false) }}
  {%- endset -%}
  {{ include('blocks/section-frame.html.twig', {'p': {'id': v_id, 'title': v_title, 'tone': v_tone, 'density': v_density, 'align': 'center', 'landmarkLabel': v_landmarkLabel}, 'children': c_4}, with_context = false) }}
{%- endif %}
